             f"{FACE_SERVICE_TOKEN_FILE_ENV} (token file must match the service)"
         ) from exc

     @staticmethod
     def _raise_shape_config(op: str, exc: FaceServiceHttpError) -> NoReturn:
         raise ProviderConfigError(
