     # ------------------------------------------------------------ same_person
     def same_person(self, images: dict[str, bytes]) -> SamePersonResult:
         # 先做入参完整性校验（零网络 fail-closed），再调用两次比较。
         for view in REQUIRED_VIEWS_ALL:
             if images.get(view) is None:
